export async function listTools() {
  return [
    {
      name: 'run_with_progress',
      description: 'Run a task reporting monotonic progress from 0 to 1',
      inputSchema: {
        type: 'object',
        properties: {
          steps: { type: 'integer', minimum: 1, description: 'Number of steps (positive integer)' }
        },
        required: ['steps']
      }
    }
  ];
}

export async function callTool(name, args, context) {
  if (name !== 'run_with_progress') {
    const error = new Error('Unknown tool: ' + name);
    error.code = -32602;
    throw error;
  }
  const steps = args.steps;
  if (!Number.isInteger(steps) || steps < 1) {
    const error = new Error('steps must be a positive integer');
    error.code = -32602;
    throw error;
  }
  const onProgress = context && typeof context.onProgress === 'function' ? context.onProgress : null;
  for (let i = 0; i <= steps; i++) {
    if (onProgress) onProgress(i / steps);
  }
  return { content: [{ type: 'text', text: 'completed' }] };
}
```

